require_once __DIR__ . '/functions.php'; if (logged_in()) { header('Location: index.php'); exit; }
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verify_csrf(); $username = trim($_POST['username'] ?? ''); $password = $_POST['password'] ?? ''; $confirm = $_POST['confirm_password'] ?? ''; if (!preg_match('/^[A-Za-z0-9_]{3,30}$/', $username)) { flash('error', 'Username must be 3–30 letters, numbers, or underscores.'); } elseif (strlen($password) < 6) { flash('error', 'Password must be at least 6 characters.'); } elseif ($password !== $confirm) { flash('error', 'Passwords do not match.'); } else { try { $stmt = db()->prepare('INSERT INTO users (username, password) VALUES (?, ?)'); $stmt->execute([$username, password_hash($password, PASSWORD_DEFAULT)]); flash('success', 'Account created. You can now log in.'); header('Location: login.php'); exit; } catch (PDOException $e) { flash('error', 'That username is already in use.'); } } }
$page_title = 'Register'; require __DIR__ . '/header.php'; ?>
<form class="auth-card" method="post" novalidate data-register-form><input type="hidden" name="csrf_token" value="<?= csrf_token() ?>"><p class="eyebrow">Join the archive</p><h1>Create an account</h1><label>Username<input name="username" required minlength="3" maxlength="30" pattern="[A-Za-z0-9_]+" autocomplete="username" value="<?= e($_POST['username'] ?? '') ?>"></label><label>Password<input type="password" name="password" required minlength="6" autocomplete="new-password"></label><label>Confirm password<input type="password" name="confirm_password" required minlength="6" autocomplete="new-password"></label><button class="button" type="submit">Register</button><p>Already registered? <a href="login.php">Log in</a></p></form>
